class Packrat
  def initialize(src)
    @src = src
    @memo = {}                              # or Hash.new { |h, k| h[k] = compute(k) }
  end

  def rule(id, pos)
    key = [id, pos].freeze                  # Array keys compare by hash + eql?
    return @memo[key] if @memo.key?(key)    # key?(), because nil means nothing
    @memo[key] = rule_impl(id, pos)         # store Fail, not nil, for a failed rule
  end
end
